"""Edge coverage bitmap (64KB shared memory simulation)."""

from __future__ import annotations

import hashlib
from typing import Dict, Iterable, Mapping, Sequence, Set, Union


MAP_SIZE = 65536  # 64KB bitmap


TraceInput = Union[Set[int], Mapping[int, int], Sequence[int]]


def bucket_hit_count(count: int) -> int:
    """Map a raw hit count to AFL's bucketed representation."""
    if count <= 0:
        return 0
    if count == 1:
        return 1
    if count == 2:
        return 2
    if count == 3:
        return 3
    if count <= 7:
        return 4
    if count <= 15:
        return 8
    if count <= 31:
        return 16
    if count <= 127:
        return 32
    return 128


def classify_counts(counts: TraceInput) -> TraceInput:
    """Bucket raw hit counts into AFL's canonical hit-count classes."""
    if isinstance(counts, set):
        return set(counts)
    if isinstance(counts, Mapping):
        return {idx: bucket_hit_count(value) for idx, value in counts.items() if value > 0}
    return [bucket_hit_count(value) for value in counts]


class CoverageBitmap:
    """Simulates AFL's 64KB shared memory coverage bitmap.

    The class supports two styles of input:
    - exact edge identifiers as a ``set[int]`` for compatibility with the base
      simulation framework
    - bitmap slot hit counts as ``dict[int, int]`` for AFL-style bucketing
    """

    def __init__(self):
        self.counts = bytearray(MAP_SIZE)
        self.global_coverage: Set[int] = set()
        self.virgin_bits: Set[int] = set()

    @staticmethod
    def edge_index(prev_block: int, cur_block: int) -> int:
        """Return the AFL bitmap slot for the given edge transition."""
        return ((prev_block ^ cur_block) >> 1) & (MAP_SIZE - 1)

    def trace_blocks(self, block_trace: Sequence[int]) -> Dict[int, int]:
        """Convert a sequence of blocks into AFL bitmap hit counts."""
        slot_counts: Dict[int, int] = {}
        prev_block = 0
        for cur_block in block_trace[1:]:
            slot = self.edge_index(prev_block, cur_block)
            slot_counts[slot] = slot_counts.get(slot, 0) + 1
            prev_block = cur_block >> 1
        return slot_counts

    def _normalize(self, trace: TraceInput) -> Dict[int, int]:
        if isinstance(trace, set):
            return {idx & (MAP_SIZE - 1): 1 for idx in trace}
        if isinstance(trace, Mapping):
            return {idx & (MAP_SIZE - 1): int(value) for idx, value in trace.items() if value > 0}
        return {
            idx: int(value)
            for idx, value in enumerate(trace[:MAP_SIZE])
            if int(value) > 0
        }

    def has_new_bits(self, trace: TraceInput) -> bool:
        """Return True when the trace exposes a previously unseen slot."""
        normalized = self._normalize(trace)
        return any(slot not in self.global_coverage for slot in normalized)

    def update(self, trace: TraceInput) -> Set[int]:
        """Merge a trace into the global bitmap and return newly discovered slots."""
        normalized = self._normalize(trace)
        new_slots: Set[int] = set()
        for slot, raw_count in normalized.items():
            bucket = bucket_hit_count(raw_count)
            if bucket == 0:
                continue
            if self.counts[slot] == 0:
                new_slots.add(slot)
                self.global_coverage.add(slot)
            if bucket > self.counts[slot]:
                self.counts[slot] = bucket
        self.virgin_bits.update(new_slots)
        return new_slots

    def trace_hash(self, trace: TraceInput) -> str:
        """Return a stable hash for crash deduplication and path identity."""
        normalized = classify_counts(self._normalize(trace))
        digest = hashlib.sha1()
        if isinstance(normalized, Mapping):
            for slot, value in sorted(normalized.items()):
                digest.update(slot.to_bytes(2, "little", signed=False))
                digest.update(bytes((value,)))
        else:
            for slot in sorted(normalized):
                digest.update(slot.to_bytes(2, "little", signed=False))
        return digest.hexdigest()

    def get_coverage_count(self) -> int:
        """Return the number of unique bitmap slots hit so far."""
        return len(self.global_coverage)

    def get_coverage_percentage(self, total_edges: int) -> float:
        """Return coverage as a percentage of total edges."""
        if total_edges == 0:
            return 0.0
        return len(self.global_coverage) / total_edges * 100.0

    def snapshot(self) -> Dict[int, int]:
        """Return a sparse view of the current bitmap."""
        return {slot: self.counts[slot] for slot in self.global_coverage}

    def reset(self):
        """Reset the bitmap to empty state."""
        self.counts = bytearray(MAP_SIZE)
        self.global_coverage.clear()
        self.virgin_bits.clear()

