"""Core AFL simulation with deterministic stages and queue management."""

from __future__ import annotations

import hashlib
import math
from collections import Counter, defaultdict
from dataclasses import dataclass
from typing import Dict, Iterable, Iterator, List, Mapping, Optional, Sequence, Set, Tuple

import numpy as np

from fuzzsim.bitmap import CoverageBitmap
from fuzzsim.mutation import (
    INTERESTING_8,
    INTERESTING_16,
    INTERESTING_32,
    arith_add,
    arith_sub,
    bit_flip,
    byte_flip,
    clone_bytes,
    delete_bytes,
    havoc as base_havoc,
    insert_bytes,
    random_byte,
)
from fuzzsim.program_model import ExecutionTrace
from fuzzsim.seed import TestCase


INTERESTING_VALUES = {
    1: tuple(value & 0xFF for value in INTERESTING_8),
    2: tuple(value & 0xFFFF for value in INTERESTING_16),
    4: tuple(value & 0xFFFFFFFF for value in INTERESTING_32),
}


def _stable_hash(parts: Iterable[object]) -> str:
    digest = hashlib.sha1()
    for part in parts:
        digest.update(repr(part).encode("ascii", "ignore"))
        digest.update(b"|")
    return digest.hexdigest()


@dataclass(frozen=True)
class TraceResult:
    """Canonical execution result used by the AFL simulation."""

    edge_ids: Tuple[int, ...]
    bitmap_counts: Dict[int, int]
    bitmap_signature: Tuple[Tuple[int, int], ...]
    path_id: Tuple[int, ...]
    is_crash: bool
    exec_time: float
    comparisons: Tuple[Tuple[int, bytes, bytes], ...] = ()

    @property
    def coverage(self) -> Set[int]:
        return set(self.edge_ids)

    @property
    def coverage_hash(self) -> str:
        return _stable_hash(("cov", self.bitmap_signature))

    @property
    def bitmap_indices(self) -> Set[int]:
        return {index for index, _ in self.bitmap_signature}

    def __iter__(self):
        yield self.coverage
        yield self.is_crash
        yield self.exec_time


@dataclass(frozen=True)
class CalibrationResult:
    """Multi-run stability information for a queue candidate."""

    trace: TraceResult
    stability: float
    variable_slots: Set[int]
    runs: int
    avg_exec_time: float

    @property
    def is_stable(self) -> bool:
        return self.stability >= 90.0


@dataclass(frozen=True)
class CrashRecord:
    """Coverage-hash deduplicated crash."""

    data: bytes
    coverage_hash: str
    path_id: Tuple[int, ...]
    bitmap_signature: Tuple[Tuple[int, int], ...]
    exec_time: float


@dataclass(frozen=True)
class AFLRunSummary:
    """High-level run statistics for experiments and tests."""

    execs: int
    fork_count: int
    queue_cycles: int
    paths_discovered: int
    unique_crashes: int
    corpus_size: int
    edge_coverage: float
    favored_seeds: int
    mean_energy: float

    def as_dict(self) -> Dict[str, float | int]:
        return {
            "execs": self.execs,
            "fork_count": self.fork_count,
            "queue_cycles": self.queue_cycles,
            "paths_discovered": self.paths_discovered,
            "unique_crashes": self.unique_crashes,
            "corpus_size": self.corpus_size,
            "edge_coverage": self.edge_coverage,
            "favored_seeds": self.favored_seeds,
            "mean_energy": self.mean_energy,
        }


class ForkServerSimulator:
    """Simulate AFL's fork server and amortised process start-up cost."""

    def __init__(
        self,
        target: object,
        *,
        startup_overhead: float = 0.002,
        fork_overhead: float = 0.0001,
    ):
        self.target = target
        self.program = getattr(target, "program", target)
        self.bitmap = CoverageBitmap()
        self.edge_lookup = {
            edge.edge_id: edge for edge in getattr(self.program, "edges", [])
        }
        self.startup_overhead = startup_overhead
        self.fork_overhead = fork_overhead
        self.started = False
        self.exec_count = 0
        self.fork_count = 0

    def _edge_ids_to_bitmap_counts(self, edge_ids: Sequence[int]) -> Dict[int, int]:
        counts: Dict[int, int] = defaultdict(int)
        for edge_id in edge_ids:
            edge = self.edge_lookup.get(edge_id)
            if edge is None:
                slot = edge_id & (len(self.bitmap.counts) - 1)
            else:
                slot = self.bitmap.edge_index(edge.src, edge.dst)
            counts[slot] += 1
        return dict(counts)

    def _trace_to_result(self, trace: ExecutionTrace, overhead: float) -> TraceResult:
        bitmap_signature = tuple(sorted(trace.coverage_signature))
        return TraceResult(
            edge_ids=tuple(trace.edge_ids),
            bitmap_counts=dict(trace.bitmap_counts),
            bitmap_signature=bitmap_signature,
            path_id=tuple(trace.path_id),
            is_crash=trace.is_crash,
            exec_time=trace.exec_time + overhead,
            comparisons=tuple(trace.comparisons),
        )

    def execute(self, data: bytes) -> TraceResult:
        overhead = self.fork_overhead if self.started else self.startup_overhead
        self.started = True
        self.exec_count += 1
        self.fork_count += 1

        if hasattr(self.target, "trace"):
            return self._trace_to_result(self.target.trace(data), overhead)

        edges, is_crash, exec_time = self.target.execute(data)
        edge_ids = tuple(sorted(set(edges)))
        bitmap_counts = self._edge_ids_to_bitmap_counts(edge_ids)
        bitmap_signature = tuple(sorted(bitmap_counts.items()))
        return TraceResult(
            edge_ids=edge_ids,
            bitmap_counts=bitmap_counts,
            bitmap_signature=bitmap_signature,
            path_id=edge_ids,
            is_crash=bool(is_crash),
            exec_time=exec_time + overhead,
            comparisons=(),
        )

    def reset(self) -> None:
        self.started = False
        self.exec_count = 0
        self.fork_count = 0


class CrashDeduplicator:
    """Coverage-hash crash deduplication."""

    def __init__(self):
        self._seen: Set[str] = set()
        self.records: List[CrashRecord] = []

    def record(self, data: bytes, trace: TraceResult) -> bool:
        if not trace.is_crash:
            return False
        if trace.coverage_hash in self._seen:
            return False
        self._seen.add(trace.coverage_hash)
        self.records.append(
            CrashRecord(
                data=bytes(data),
                coverage_hash=trace.coverage_hash,
                path_id=tuple(trace.path_id),
                bitmap_signature=tuple(trace.bitmap_signature),
                exec_time=trace.exec_time,
            )
        )
        return True

    def __len__(self) -> int:
        return len(self.records)


class AFLFuzzer:
    """Coverage-guided greybox fuzzer with AFL-style queue and stages."""

    def __init__(
        self,
        target: object,
        initial_inputs: Optional[Sequence[bytes]] = None,
        *,
        seed: int = 42,
        calibration_runs: int = 3,
        user_dictionary: Optional[Sequence[bytes | str]] = None,
        havoc_cycles: int = 16,
        max_auto_tokens: int = 32,
        enable_trim: bool = True,
    ):
        self.target = target
        self.program = getattr(target, "program", target)
        self.rng = np.random.RandomState(seed)
        self.seed = seed
        self.fork_server = ForkServerSimulator(target)
        self.bitmap = CoverageBitmap()
        self.covered_edges: Set[int] = set()
        self.path_corpus: Set[Tuple[int, ...]] = set()
        self.queue: List[TestCase] = []
        self.crash_deduper = CrashDeduplicator()
        self.user_dictionary = self._normalize_dictionary(user_dictionary or [])
        self.auto_dictionary: List[bytes] = []
        self._auto_dictionary_seen: Set[bytes] = set()
        self.calibration_runs = calibration_runs
        self.havoc_cycles = havoc_cycles
        self.max_auto_tokens = max_auto_tokens
        self.enable_trim = enable_trim
        self.iteration = 0
        self.queue_cycles = 0
        self.energy_history: List[float] = []

        if initial_inputs is None:
            initial_inputs = [b"\x00"]
        for data in initial_inputs:
            self.seed_input(data, force=True)
        self.cull_corpus()

    def _normalize_dictionary(self, tokens: Sequence[bytes | str]) -> List[bytes]:
        seen: Set[bytes] = set()
        normalized: List[bytes] = []
        for token in tokens:
            data = token.encode("ascii", "ignore") if isinstance(token, str) else bytes(token)
            if not data or data in seen:
                continue
            seen.add(data)
            normalized.append(data)
        return normalized

    def get_total_edges(self) -> int:
        if hasattr(self.target, "get_total_edges"):
            return int(self.target.get_total_edges())
        if hasattr(self.program, "get_all_edge_ids"):
            return len(self.program.get_all_edge_ids())
        return len(getattr(self.program, "edges", []))

    def on_execution(self, _parent: Optional[TestCase], _data: bytes, _trace: TraceResult) -> None:
        """Hook for variants that track every execution."""

    def on_new_seed(self, _test_case: TestCase, _trace: TraceResult) -> None:
        """Hook for variants that maintain additional corpus metadata."""

    def should_skip_seed(self, _test_case: TestCase) -> bool:
        return False

    def seed_priority(self, test_case: TestCase) -> Tuple[object, ...]:
        return (
            test_case.was_fuzzed,
            test_case.times_chosen,
            -len(test_case.unique_edges),
            -len(test_case.coverage),
            test_case.size,
            test_case.exec_time,
            test_case.creation_time,
        )

    def _read_int(self, data: bytes, offset: int, width: int, byteorder: str) -> Optional[int]:
        if offset + width > len(data):
            return None
        return int.from_bytes(data[offset:offset + width], byteorder=byteorder, signed=False)

    def _write_int(self, data: bytes, offset: int, width: int, value: int, byteorder: str) -> bytes:
        if offset + width > len(data):
            return data
        mask = (1 << (width * 8)) - 1
        buffer = bytearray(data)
        buffer[offset:offset + width] = int(value & mask).to_bytes(width, byteorder=byteorder)
        return bytes(buffer)

    def execute(self, data: bytes) -> TraceResult:
        trace = self.fork_server.execute(data)
        self.on_execution(None, data, trace)
        return trace

    def calibrate(self, data: bytes, runs: Optional[int] = None) -> CalibrationResult:
        runs = max(1, runs or self.calibration_runs)
        traces = [self.fork_server.execute(data) for _ in range(runs)]
        union_slots: Set[int] = set()
        for trace in traces:
            union_slots.update(trace.bitmap_indices)

        stable_slots = 0
        variable_slots: Set[int] = set()
        for slot in union_slots:
            values = [trace.bitmap_counts.get(slot, 0) for trace in traces]
            if all(value == values[0] for value in values):
                stable_slots += 1
            else:
                variable_slots.add(slot)

        total_slots = len(union_slots)
        stability = 100.0 if total_slots == 0 else 100.0 * stable_slots / total_slots
        avg_exec_time = sum(trace.exec_time for trace in traces) / runs
        base = traces[0]
        trace = TraceResult(
            edge_ids=base.edge_ids,
            bitmap_counts=base.bitmap_counts,
            bitmap_signature=base.bitmap_signature,
            path_id=base.path_id,
            is_crash=base.is_crash,
            exec_time=avg_exec_time,
            comparisons=base.comparisons,
        )
        return CalibrationResult(
            trace=trace,
            stability=stability,
            variable_slots=variable_slots,
            runs=runs,
            avg_exec_time=avg_exec_time,
        )

    def trim_input(self, data: bytes, target_trace: Optional[TraceResult] = None) -> bytes:
        if len(data) <= 1:
            return data
        if target_trace is None:
            target_trace = self.fork_server.execute(data)

        result = bytes(data)
        block_size = 1 << max(0, len(result).bit_length() - 1)
        while block_size >= 1 and len(result) > 1:
            offset = 0
            while offset < len(result):
                if len(result) - block_size < 1:
                    offset += block_size
                    continue
                candidate = result[:offset] + result[offset + block_size:]
                if not candidate:
                    candidate = b"\x00"
                trace = self.fork_server.execute(candidate)
                if (
                    trace.bitmap_signature == target_trace.bitmap_signature
                    and trace.is_crash == target_trace.is_crash
                ):
                    result = candidate
                    continue
                offset += block_size
            block_size //= 2
        return result

    def extract_auto_dictionary_tokens(self, data: bytes) -> List[bytes]:
        """Extract printable token substrings up to eight bytes long."""
        runs: List[bytes] = []
        current = bytearray()
        for value in data + b"\x00":
            if 32 <= value <= 126:
                current.append(value)
                continue
            if len(current) >= 2:
                runs.append(bytes(current))
            current.clear()

        tokens: List[bytes] = []
        seen: Set[bytes] = set()
        for run in runs:
            max_width = min(8, len(run))
            for width in range(2, max_width + 1):
                for start in range(0, len(run) - width + 1):
                    token = run[start:start + width]
                    if token in seen:
                        continue
                    seen.add(token)
                    tokens.append(token)
        return tokens

    def add_auto_dictionary_tokens(self, tokens: Sequence[bytes]) -> None:
        for token in tokens:
            if not token or token in self._auto_dictionary_seen:
                continue
            self._auto_dictionary_seen.add(token)
            self.auto_dictionary.append(token)
            if len(self.auto_dictionary) > self.max_auto_tokens:
                removed = self.auto_dictionary.pop(0)
                self._auto_dictionary_seen.discard(removed)

    def iter_bitflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width in (1, 2, 4):
            for bit_index in range(max(0, len(data) * 8 - width + 1)):
                if width == 1 and bit_index % 8 == 0:
                    byte_index = bit_index // 8
                    window = data[max(0, byte_index - 4):byte_index + 8]
                    self.add_auto_dictionary_tokens(self.extract_auto_dictionary_tokens(window))
                yield (f"bitflip-{width}", bit_flip(data, bit_index, width=width))

    def iter_byteflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width in (1, 2, 4):
            for offset in range(max(0, len(data) - width + 1)):
                yield (f"byteflip-{width * 8}", byte_flip(data, offset, width=width))

    def iter_arithmetic_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width in (1, 2, 4):
            for offset in range(max(0, len(data) - width + 1)):
                orders = ("little", "big") if width > 1 else ("little",)
                for byteorder in orders:
                    current = self._read_int(data, offset, width, byteorder)
                    if current is None:
                        continue
                    for delta in range(1, 36):
                        yield (
                            f"arith-add-{width * 8}-{byteorder}",
                            self._write_int(data, offset, width, current + delta, byteorder),
                        )
                        yield (
                            f"arith-sub-{width * 8}-{byteorder}",
                            self._write_int(data, offset, width, current - delta, byteorder),
                        )

    def iter_interesting_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width, values in INTERESTING_VALUES.items():
            for offset in range(max(0, len(data) - width + 1)):
                orders = ("little", "big") if width > 1 else ("little",)
                for byteorder in orders:
                    for value in values:
                        yield (
                            f"interest-{width * 8}-{byteorder}",
                            self._write_int(data, offset, width, value, byteorder),
                        )

    def iter_dictionary_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        seen: Set[Tuple[str, bytes]] = set()
        for token in self.user_dictionary + self.auto_dictionary:
            if not token:
                continue
            for offset in range(len(data) + 1):
                candidate = insert_bytes(data, offset, token)
                marker = ("insert", candidate)
                if marker not in seen:
                    seen.add(marker)
                    yield ("dict-insert", candidate)
            if len(token) > len(data):
                continue
            for offset in range(len(data) - len(token) + 1):
                buffer = bytearray(data)
                buffer[offset:offset + len(token)] = token
                candidate = bytes(buffer)
                marker = ("overwrite", candidate)
                if marker not in seen:
                    seen.add(marker)
                    yield ("dict-overwrite", candidate)

    def iter_deterministic_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for generator in (
            self.iter_bitflip_mutations,
            self.iter_byteflip_mutations,
            self.iter_arithmetic_mutations,
            self.iter_interesting_mutations,
            self.iter_dictionary_mutations,
        ):
            yield from generator(data)

    def _select_mutation_positions(
        self,
        data: bytes,
        allowed_positions: Optional[Sequence[int]] = None,
        *,
        include_end: bool = False,
    ) -> List[int]:
        if allowed_positions is None:
            upper = len(data) + (1 if include_end else 0)
            return list(range(max(1, upper)))
        positions = sorted({pos for pos in allowed_positions if 0 <= pos < len(data)})
        if include_end:
            positions.append(len(data))
        return positions or ([0] if not include_end else [0, len(data)])

    def _choose_position(
        self,
        data: bytes,
        allowed_positions: Optional[Sequence[int]] = None,
        *,
        include_end: bool = False,
    ) -> int:
        positions = self._select_mutation_positions(
            data,
            allowed_positions,
            include_end=include_end,
        )
        return positions[int(self.rng.randint(0, len(positions)))]

    def _havoc_operator(
        self,
        data: bytes,
        allowed_positions: Optional[Sequence[int]] = None,
    ) -> bytes:
        if not data:
            data = b"\x00"
        op = int(self.rng.randint(0, 11))
        pos = self._choose_position(data, allowed_positions)

        if op == 0:
            bit_pos = pos * 8 + int(self.rng.randint(0, 8))
            return bit_flip(data, bit_pos)
        if op == 1:
            return byte_flip(data, pos)
        if op == 2:
            return arith_add(data, pos, value=int(self.rng.randint(1, 36)))
        if op == 3:
            return arith_sub(data, pos, value=int(self.rng.randint(1, 36)))
        if op == 4:
            return random_byte(data, pos, self.rng)
        if op == 5 and len(data) > 1:
            safe_positions = self._select_mutation_positions(data, allowed_positions)
            start = safe_positions[int(self.rng.randint(0, len(safe_positions)))]
            max_len = min(4, len(data) - start)
            if max_len > 0:
                return delete_bytes(data, start, int(self.rng.randint(1, max_len + 1)))
        if op == 6:
            insert_at = self._choose_position(data, allowed_positions, include_end=True)
            size = int(self.rng.randint(1, 5))
            payload = bytes(self.rng.randint(0, 256, size=size).astype(np.uint8))
            return insert_bytes(data, insert_at, payload)
        if op == 7 and len(data) > 1:
            width = int(self.rng.randint(1, min(4, len(data)) + 1))
            src = int(self.rng.randint(0, len(data) - width + 1))
            dst = int(self.rng.randint(0, len(data) - width + 1))
            return clone_bytes(data, src, dst, width)
        if op == 8 and (self.user_dictionary or self.auto_dictionary):
            token_pool = self.user_dictionary + self.auto_dictionary
            token = token_pool[int(self.rng.randint(0, len(token_pool)))]
            insert_at = self._choose_position(data, allowed_positions, include_end=True)
            return insert_bytes(data, insert_at, token)
        if op == 9 and len(data) >= 2:
            safe_positions = self._select_mutation_positions(data, allowed_positions)
            start = safe_positions[int(self.rng.randint(0, len(safe_positions)))]
            end = min(len(data), start + int(self.rng.randint(1, min(5, len(data) - start + 1))))
            buffer = bytearray(data)
            buffer[start:end] = reversed(buffer[start:end])
            return bytes(buffer)
        return base_havoc(data, self.rng, num_mutations=int(self.rng.randint(1, 8)))

    def havoc_mutation(
        self,
        data: bytes,
        *,
        test_case: Optional[TestCase] = None,
        allowed_positions: Optional[Sequence[int]] = None,
    ) -> bytes:
        del test_case
        depth = 2 ** int(self.rng.randint(1, 8))
        result = bytes(data)
        for _ in range(depth):
            result = self._havoc_operator(result, allowed_positions)
        return result

    def splice_inputs(self, first: bytes, second: bytes) -> bytes:
        if len(first) < 2 or len(second) < 2:
            return first
        midpoint = min(len(first), len(second)) // 2
        return first[:midpoint] + second[midpoint:]

    def splice_mutation(self, test_case: TestCase) -> bytes:
        others = [candidate for candidate in self.queue if candidate is not test_case]
        if not others:
            return self.havoc_mutation(test_case.data, test_case=test_case)
        partner = others[int(self.rng.randint(0, len(others)))]
        spliced = self.splice_inputs(test_case.data, partner.data)
        return self.havoc_mutation(spliced, test_case=test_case)

    def calculate_performance_score(self, test_case: TestCase) -> float:
        if not self.queue:
            return 100.0
        avg_exec = sum(item.exec_time for item in self.queue) / len(self.queue)
        avg_cov = sum(len(item.coverage) for item in self.queue) / len(self.queue)
        speed_factor = avg_exec / max(test_case.exec_time, 1e-9)
        coverage_factor = max(1.0, len(test_case.coverage) / max(avg_cov, 1.0))
        depth_factor = 1.0 + min(test_case.depth, 10) * 0.05
        stability_factor = max(0.5, test_case.stability / 100.0)
        score = 100.0 * speed_factor * coverage_factor * depth_factor * stability_factor
        return float(min(500.0, max(25.0, score)))

    def compute_energy(self, test_case: TestCase) -> float:
        score = self.calculate_performance_score(test_case)
        test_case.perf_score = score
        test_case.energy = score
        return score

    def mutation_budget(self, energy: float) -> int:
        return max(1, min(self.havoc_cycles, int(math.ceil(energy / 25.0))))

    def seed_input(self, data: bytes, *, force: bool = False, depth: int = 0) -> Optional[TestCase]:
        calibration = self.calibrate(data)
        candidate_data = bytes(data)
        candidate_trace = calibration.trace

        if self.enable_trim:
            candidate_data = self.trim_input(candidate_data, target_trace=candidate_trace)
            if candidate_data != data:
                calibration = self.calibrate(candidate_data)
                candidate_trace = calibration.trace

        new_bits = self.bitmap.has_new_bits(candidate_trace.bitmap_counts)
        new_path = candidate_trace.path_id not in self.path_corpus
        unique_crash = self.crash_deduper.record(candidate_data, candidate_trace)
        if not (force or new_bits or new_path or unique_crash):
            return None

        test_case = TestCase(
            data=candidate_data,
            coverage=set(candidate_trace.coverage),
            exec_time=candidate_trace.exec_time,
            is_crash=candidate_trace.is_crash,
            depth=depth,
            creation_time=self.iteration,
            stability=calibration.stability,
            path_id=tuple(candidate_trace.path_id),
            bitmap_signature=tuple(candidate_trace.bitmap_signature),
            metadata={
                "variable_slots": set(calibration.variable_slots),
                "comparisons": tuple(candidate_trace.comparisons),
                "calibration_runs": calibration.runs,
            },
        )
        test_case.perf_score = self.calculate_performance_score(test_case)
        test_case.energy = test_case.perf_score

        self.bitmap.update(candidate_trace.bitmap_counts)
        self.covered_edges.update(candidate_trace.coverage)
        self.path_corpus.add(candidate_trace.path_id)
        self.queue.append(test_case)
        self.on_new_seed(test_case, candidate_trace)
        self.cull_corpus()
        return test_case

    def cull_corpus(self) -> List[TestCase]:
        if not self.queue:
            return []

        for test_case in self.queue:
            test_case.is_favored = False
            test_case.metadata["favored_edges"] = set()
            test_case.unique_edges.clear()

        best_for_edge: Dict[int, TestCase] = {}
        for test_case in self.queue:
            for edge in test_case.coverage:
                current = best_for_edge.get(edge)
                if current is None:
                    best_for_edge[edge] = test_case
                    continue
                current_key = (current.size, current.exec_time, -len(current.coverage), current.depth)
                candidate_key = (
                    test_case.size,
                    test_case.exec_time,
                    -len(test_case.coverage),
                    test_case.depth,
                )
                if candidate_key < current_key:
                    best_for_edge[edge] = test_case

        uncovered = set(best_for_edge)
        candidates = set(best_for_edge.values())
        favored: List[TestCase] = []
        while uncovered and candidates:
            best = min(
                candidates,
                key=lambda item: (
                    -len(item.coverage & uncovered),
                    item.size,
                    item.exec_time,
                    item.creation_time,
                ),
            )
            contributed = best.coverage & uncovered
            if not contributed:
                break
            best.is_favored = True
            best.metadata["favored_edges"] = set(contributed)
            favored.append(best)
            uncovered -= contributed
            candidates.remove(best)

        edge_frequency = Counter(edge for item in self.queue for edge in item.coverage)
        for test_case in self.queue:
            test_case.unique_edges = {
                edge for edge in test_case.coverage if edge_frequency[edge] == 1
            }
        return favored

    def select_seed(self) -> TestCase:
        favored_pool = [test_case for test_case in self.queue if test_case.is_favored]
        other_pool = [test_case for test_case in self.queue if not test_case.is_favored]
        pick_favored = favored_pool and self.rng.rand() < 0.75
        pool = favored_pool if pick_favored else (other_pool or favored_pool or self.queue)
        ranked = sorted(pool, key=self.seed_priority)
        top_k = min(3, len(ranked))
        test_case = ranked[int(self.rng.randint(0, top_k))]
        test_case.times_chosen += 1
        return test_case

    def evaluate_input(
        self,
        data: bytes,
        *,
        parent: Optional[TestCase] = None,
        trim: Optional[bool] = None,
    ) -> Optional[TestCase]:
        self.iteration += 1
        trace = self.fork_server.execute(data)
        self.on_execution(parent, data, trace)

        new_bits = self.bitmap.has_new_bits(trace.bitmap_counts)
        new_path = trace.path_id not in self.path_corpus
        unique_crash = self.crash_deduper.record(data, trace)
        if not (new_bits or new_path or unique_crash):
            return None

        previous_trim = self.enable_trim
        if trim is not None:
            self.enable_trim = trim
        try:
            return self.seed_input(data, depth=(0 if parent is None else parent.depth + 1))
        finally:
            self.enable_trim = previous_trim

    def process_seed(self, test_case: TestCase) -> int:
        if self.should_skip_seed(test_case):
            return 0

        discoveries = 0
        if not test_case.was_fuzzed:
            for _stage, mutated in self.iter_deterministic_mutations(test_case.data):
                if self.evaluate_input(mutated, parent=test_case) is not None:
                    discoveries += 1

        energy = self.compute_energy(test_case)
        self.energy_history.append(energy)
        for _ in range(self.mutation_budget(energy)):
            mutated = self.havoc_mutation(test_case.data, test_case=test_case)
            if self.evaluate_input(mutated, parent=test_case) is not None:
                discoveries += 1

        if len(self.queue) > 1:
            spliced = self.splice_mutation(test_case)
            if self.evaluate_input(spliced, parent=test_case) is not None:
                discoveries += 1

        test_case.fuzz_count += 1
        test_case.was_fuzzed = True
        self.cull_corpus()
        return discoveries

    def step(self) -> int:
        if not self.queue:
            return 0
        self.queue_cycles += 1
        test_case = self.select_seed()
        return self.process_seed(test_case)

    def run(self, cycles: int = 3) -> AFLRunSummary:
        for _ in range(max(0, cycles)):
            self.step()

        total_edges = self.get_total_edges()
        coverage = 0.0
        if total_edges:
            coverage = round(len(self.covered_edges) / total_edges * 100.0, 1)
        mean_energy = 0.0
        if self.energy_history:
            mean_energy = round(sum(self.energy_history) / len(self.energy_history), 1)
        return AFLRunSummary(
            execs=self.fork_server.exec_count,
            fork_count=self.fork_server.fork_count,
            queue_cycles=self.queue_cycles,
            paths_discovered=len(self.path_corpus),
            unique_crashes=len(self.crash_deduper),
            corpus_size=len(self.queue),
            edge_coverage=coverage,
            favored_seeds=sum(1 for item in self.queue if item.is_favored),
            mean_energy=mean_energy,
        )


